dataTableFormat:
{
  "is multi section": "true",
  "search parameters": [
    {
      "parameter": "phenotype",
      "label": "Phenotype",
      "type": "list",
      "values": [
        {
          "label": "SLE",
          "value": "SLE"
        }
      ]
    },
    {
      "parameter": "ancestry",
      "label": "Ancestry",
      "type": "list",
      "values": [
        {
          "label": "European",
          "value": "eu"
        }
      ]
    },
    {
      "parameter": "region",
      "label": "Set region (PCSK9,chr:start-end)",
      "type": "input",
      "values": "kp genes",
      "convert to region": "true",
      "expand region by": 100000
    },
    {
      "parameter": "tissue",
      "label": "Tissue",
      "type": "input",
      "display": "false"
    },
    {
      "parameter": "tissueUnderscored",
      "label": "Tissue",
      "type": "input",
      "display": "false"
    },
    {
      "parameter": "clump",
      "label": "clump",
      "type": "input",
      "display": "false"
    },
    {
      "parameter": "csid",
      "label": "CS ID",
      "type": "input",
      "display": "false"
    }
  ],
  "tab groups": [
    {
      "label": "Phenotype Associations",
      "sections": [
        {
          "section": "associations",
          "label": "Associated variants in region"
        },
        {
          "section": "global_associations",
          "label": "Genome-wide associations"
        },
        {
          "section": "gene_finder",
          "label": "Associated genes"
        }
      ]
    },
    {
      "label": "credible variants",
      "sections": [
        {
          "section": "credible_sets",
          "label": "Other credible sets in region"
        },
        {
          "section": "credible_variants",
          "label": "Variants in credible set"
        }
      ]
    },
    {
      "label": "Tissue / Annotation",
      "sections": [
        {
          "section": "global_enrichment",
          "label": "Globally Enriched Tissues / Annotations"
        },
        {
          "section": "regions",
          "label": "Tissue-level annotations"
        },
        {
          "section": "tissue_regions",
          "label": "Biosample-level annotations"
        }
      ]
    },
    {
      "label": "Gene Links",
      "sections": [
        {
          "section": "gene_links",
          "label": "Target gene links"
        },
        {
          "section": "variant_links",
          "label": "SNP to Gene Links"
        }
      ]
    },
    {
      "label": "Summary",
      "type": "fixed bottom",
      "sections": [
        {
          "section": "page_summary",
          "label": "Page Summary"
        }
      ]
    }
  ],
  "sections": [
    {
      "section id": "credible_variants",
      "header": "Credible Variants",
      "data point": {
        "type": "bioindex",
        "url": "https://lupus.hugeampkpnbi.org/api/bio/",
        "index": "credible-variants",
        "parameters": [
          "phenotype",
          "ancestry",
          "csid"
        ],
        "cumulate data": "true",
        "parameters type": "array",
        "data type": "bioindex",
        "region": "region"
      },
      "table format": {
        "data convert": [
          {
            "type": "join multi",
            "field name": "Variant ID",
            "fields to join": [
              "chromosome",
              "position",
              "reference",
              "alt"
            ],
            "join by": [
              ":",
              "_",
              "/"
            ]
          },
          {
            "type": "raw",
            "field name": "CV Variant ID",
            "raw field": "Variant ID"
          },
          {
            "type": "join multi",
            "field name": "Ref/Alt",
            "fields to join": [
              "reference",
              "alt"
            ],
            "join by": [
              "/"
            ]
          },
          {
            "type": "raw",
            "field name": "PPO",
            "raw field": "posteriorProbability"
          },
          {
            "type": "raw",
            "field name": "CS ID",
            "raw field": "credibleSetId"
          },
          {
            "type": "raw",
            "field name": "Dataset",
            "raw field": "dataset"
          },
          {
            "type": "raw",
            "field name": "Method",
            "raw field": "method"
          },
          {
            "type": "raw",
            "field name": "EAF",
            "raw field": "eaf"
          },
          {
            "type": "raw",
            "field name": "PMID",
            "raw field": "pmid"
          },
          {
            "type": "raw",
            "field name": "Position",
            "raw field": "position"
          }
        ],
        "top rows": [
          "Variant ID",
          "PPO",
          "CS ID",
          "Dataset",
          "EAF",
          "Method",
          "Position",
          "PMID"
        ],
        "locus field": "CS region",
        "star column": "Variant ID",
        "column formatting": {
          "PPO": {
            "type": [
              "scientific notation"
            ]
          }
        }
      },
      "filters": [
        {
          "field": "PPO",
          "label": "PPO(>=)",
          "type": "search greater than",
          "label in bubble": "true"
        },
        {
          "field": "EAF",
          "label": "EAF(>=)",
          "type": "search greater than",
          "label in bubble": "true"
        },
        {
          "field": "Dataset",
          "label": "Dataset",
          "type": "checkbox",
          "label in bubble": "true"
        },
        {
          "field": "Method",
          "label": "Method",
          "type": "checkbox",
          "label in bubble": "true"
        },
        {
          "field": "PMID",
          "label": "PMID",
          "type": "checkbox",
          "label in bubble": "true"
        }
      ]
    },
    {
      "section id": "credible_sets",
      "header": "Credible Sets",
      "data point": {
        "type": "bioindex",
        "url": "https://lupus.hugeampkpnbi.org/api/bio/",
        "index": "credible-sets",
        "parameters": [
          "phenotype",
          "ancestry",
          "region"
        ],
        "parameters type": "array",
        "data type": "bioindex"
      },
      "table format": {
        "data convert": [
          {
            "type": "raw",
            "field name": "CS ID",
            "raw field": "credibleSetId"
          },
          {
            "type": "join multi",
            "field name": "CS region",
            "fields to join": [
              "chromosome",
              "start",
              "end"
            ],
            "join by": [
              ":",
              "-"
            ]
          },
          {
            "type": "calculate",
            "calculation type": "math",
            "field name": "region length",
            "expression": [
              "end",
              "-",
              "start"
            ],
            "note": "required to get clumped region center"
          },
          {
            "type": "join multi",
            "field name": "CS region (length)",
            "fields to join": [
              "CS region",
              "region length"
            ],
            "join by": [
              " (",
              "bp)"
            ]
          },
          {
            "type": "raw",
            "field name": "Dataset",
            "raw field": "dataset"
          },
          {
            "type": "raw",
            "field name": "Method",
            "raw field": "method"
          },
          {
            "type": "raw",
            "field name": "PMID",
            "raw field": "pmid"
          }
        ],
        "top rows": [
          "CS ID",
          "CS region (length)",
          "Dataset",
          "Method",
          "PMID"
        ],
        "column formatting": {
          "CS ID": {
            "type": [
              "set parameter"
            ],
            "target sections": [
              {
                "section": "all",
                "label": "Load variants to CS variants table",
                "parameter": [
                  "csid"
                ]
              }
            ]
          }
        }
      },
      "filters": [
        {
          "field": "Dataset",
          "label": "Dataset",
          "type": "checkbox",
          "label in bubble": "true"
        },
        {
          "field": "Method",
          "label": "Method",
          "type": "checkbox",
          "label in bubble": "true"
        },
        {
          "field": "PMID",
          "label": "PMID",
          "type": "checkbox",
          "label in bubble": "true"
        }
      ]
    },
    {
      "section id": "gene_finder",
      "header": "Gene Finder",
      "data point": {
        "type": "bioindex",
        "url": "https://lupus.hugeampkpnbi.org/api/bio/",
        "index": "gene-finder",
        "parameters": [
          "phenotype",
          "ancestry"
        ],
        "parameters type": "array",
        "data type": "bioindex"
      },
      "table format": {
        "initial sort by": {
          "field": "P-Value",
          "type": "number",
          "direction": "desc"
        },
        "data convert": [
          {
            "type": "raw",
            "field name": "Gene",
            "raw field": "gene"
          },
          {
            "type": "join multi",
            "field name": "Region",
            "fields to join": [
              "chromosome",
              "start",
              "end"
            ],
            "join by": [
              ":",
              "-"
            ]
          },
          {
            "type": "calculate",
            "field name": "Start",
            "expression": [
              "start",
              "-",
              50000
            ],
            "calculation type": "math"
          },
          {
            "type": "calculate",
            "field name": "End",
            "expression": [
              "end",
              "+",
              50000
            ],
            "calculation type": "math"
          },
          {
            "type": "join multi",
            "field name": "View Region(Gene +-50K)",
            "fields to join": [
              "chromosome",
              "Start",
              "End"
            ],
            "join by": [
              ":",
              "-"
            ]
          },
          {
            "type": "join multi",
            "field name": "Gene Region",
            "fields to join": [
              "chromosome",
              "start",
              "end"
            ],
            "join by": [
              ":",
              "-"
            ]
          },
          {
            "type": "raw",
            "field name": "P-Value",
            "raw field": "pValue"
          },
          {
            "type": "raw",
            "field name": "P-Value (Gene Level)",
            "raw field": "pValue"
          },
          {
            "type": "calculate",
            "field name": "-log10(P-Value)",
            "raw field": "pValue",
            "calculation type": "-log10"
          },
          {
            "type": "raw",
            "field name": "Z Stat",
            "raw field": "zStat"
          },
          {
            "type": "raw",
            "field name": "Sample",
            "raw field": "subjects"
          }
        ],
        "top rows": [
          "Gene",
          "View Region(Gene +-50K)",
          "P-Value",
          "Z Stat",
          "Sample"
        ],
        "column formatting": {
          "P-Value (Gene Level)": {
            "type": [
              "scientific notation"
            ]
          },
          "P-Value": {
            "type": [
              "scientific notation"
            ]
          },
          "Z Stat": {
            "type": [
              "scientific notation"
            ]
          },
          "View Region(Gene +-50K)": {
            "type": [
              "set parameter"
            ],
            "target sections": [
              {
                "section": "all",
                "label": "Set Region",
                "parameter": [
                  "region"
                ]
              }
            ]
          }
        }
      },
      "pre filters": [
        {
          "field": "P-Value",
          "value": 0.05,
          "parameter": "pValue",
          "type": "search lower than"
        }
      ],
      "visualizer": {
        "label": "",
        "type": "manhattan bitmap plot",
        "x axis field": "Region",
        "y axis field": "-log10(P-Value)",
        "render by": "Gene",
        "y axis label": "-log10(P-Value)",
        "x axis label": "",
        "hover content": [
          "P-Value",
          "Z Stat",
          "Sample"
        ],
        "height": 100
      }
    },
    {
      "section id": "global_associations",
      "header": "Global Associations",
      "data point": {
        "type": "bioindex",
        "url": "https://lupus.hugeampkpnbi.org/api/bio/",
        "index": "global-associations",
        "parameters": [
          "phenotype",
          "ancestry"
        ],
        "parameters type": "array",
        "data type": "bioindex"
      },
      "table format": {
        "data convert": [
          {
            "type": "join multi",
            "field name": "Variant ID",
            "fields to join": [
              "chromosome",
              "position",
              "reference",
              "alt"
            ],
            "join by": [
              ":",
              "_",
              "/"
            ]
          },
          {
            "type": "raw",
            "field name": "RSID",
            "raw field": "dbSNP"
          },
          {
            "type": "raw",
            "field name": "Phenotype",
            "raw field": "phenotype"
          },
          {
            "type": "raw",
            "field name": "P-Value",
            "raw field": "pValue"
          },
          {
            "type": "calculate",
            "field name": "-Log10(p)",
            "raw field": "pValue",
            "calculation type": "-log10"
          },
          {
            "type": "raw",
            "field name": "Beta",
            "raw field": "beta"
          },
          {
            "type": "raw",
            "field name": "MAF",
            "raw field": "maf"
          },
          {
            "type": "raw",
            "field name": "Standard Error",
            "raw field": "stdErr"
          },
          {
            "type": "array to string",
            "field name": "Nearest Gene",
            "raw field": "nearest",
            "separate by": ","
          },
          {
            "type": "calculate",
            "calculation type": "math",
            "field name": "region center",
            "expression": [
              "(",
              "clumpStart",
              "+",
              "clumpEnd",
              ")",
              "/",
              2
            ],
            "note": "required to get clumped region center"
          },
          {
            "type": "js math",
            "field name": "regionCenterRounded",
            "raw field": "region center",
            "method": "round"
          },
          {
            "type": "calculate",
            "calculation type": "math",
            "field name": "regionStart",
            "expression": [
              "regionCenterRounded",
              "-",
              200000
            ],
            "note": ""
          },
          {
            "type": "calculate",
            "calculation type": "math",
            "field name": "regionEnd",
            "expression": [
              "regionCenterRounded",
              "+",
              200000
            ],
            "note": ""
          },
          {
            "type": "join multi",
            "field name": "Clumped Region (center +-200K)",
            "fields to join": [
              "chromosome",
              "regionStart",
              "regionEnd"
            ],
            "join by": [
              ":",
              "-"
            ]
          },
          {
            "type": "raw",
            "field name": "Consequence",
            "raw field": "consequence"
          },
          {
            "type": "join multi",
            "field name": "Position",
            "fields to join": [
              "chromosome",
              "position"
            ],
            "join by": [
              ":"
            ]
          }
        ],
        "top rows": [
          "Variant ID",
          "RSID",
          "P-Value",
          "Beta",
          "MAF",
          "Standard Error",
          "Nearest Gene",
          "Clumped Region (center +-200K)",
          "Consequence"
        ],
        "column formatting": {
          "P-Value": {
            "type": [
              "scientific notation"
            ]
          },
          "P-Value (Gene Level)": {
            "type": [
              "scientific notation"
            ]
          },
          "Beta": {
            "type": [
              "scientific notation"
            ]
          },
          "MAF": {
            "type": [
              "scientific notation"
            ]
          },
          "Standard Error": {
            "type": [
              "scientific notation"
            ]
          },
          "Clumped Region (center +-200K)": {
            "type": [
              "set parameter"
            ],
            "target sections": [
              {
                "section": "all",
                "label": "Set Region",
                "parameter": [
                  "region"
                ]
              }
            ]
          },
          "Gene Region": {
            "type": [
              "set parameter"
            ],
            "target sections": [
              {
                "section": "all",
                "label": "Set Region",
                "parameter": [
                  "region"
                ]
              }
            ]
          }
        }
      },
      "pre filters": [
        {
          "field": "P-Value",
          "value": 0.05,
          "parameter": "pValue",
          "type": "search lower than"
        }
      ],
      "filters": [
        {
          "field": "Variant ID",
          "label": "Variant ID",
          "type": "search",
          "label in bubble": "true"
        },
        {
          "field": "rsID",
          "label": "rsID",
          "type": "search",
          "label in bubble": "true"
        },
        {
          "field": "P-Value",
          "label": "P-Value (&le;)",
          "type": "search lower than",
          "label in bubble": "true"
        },
        {
          "field": "Consequence",
          "label": "Consequence",
          "type": "checkbox",
          "label in bubble": "true"
        }
      ],
      "visualizer": {
        "label": "",
        "type": "manhattan bitmap plot",
        "x axis field": "Position",
        "y axis field": "-Log10(p)",
        "render by": "Variant ID",
        "y axis label": "-Log10(p)",
        "x axis label": "Chromosome",
        "hover content": [
          "P-Value"
        ],
        "height": 100
      }
    },
    {
      "section id": "associations",
      "header": "Associations",
      "data point": {
        "type": "bioindex",
        "url": "https://lupus.hugeampkpnbi.org/api/bio/",
        "index": "associations",
        "parameters": [
          "phenotype",
          "ancestry",
          "region"
        ],
        "parameters type": "array",
        "data type": "bioindex",
        "region": "region"
      },
      "table format": {
        "data zoom": {
          "chromosome": "Chromosome",
          "position": "Position"
        },
        "initial sort by": {
          "field": "P-Value",
          "type": "number",
          "direction": "desc"
        },
        "data convert": [
          {
            "type": "raw",
            "field name": "Phenotype",
            "raw field": "phenotype"
          },
          {
            "type": "raw",
            "field name": "Ancestry",
            "raw field": "ancestry"
          },
          {
            "type": "raw",
            "field name": "Chromosome",
            "raw field": "chromosome"
          },
          {
            "type": "raw",
            "field name": "Position",
            "raw field": "position"
          },
          {
            "type": "raw",
            "field name": "ref",
            "raw field": "reference"
          },
          {
            "type": "raw",
            "field name": "alt",
            "raw field": "alt"
          },
          {
            "type": "raw",
            "field name": "Beta",
            "raw field": "beta"
          },
          {
            "type": "raw",
            "field name": "MAF",
            "raw field": "maf"
          },
          {
            "type": "raw",
            "field name": "Standard Error",
            "raw field": "stdErr"
          },
          {
            "type": "raw",
            "field name": "Consequence",
            "raw field": "consequence"
          },
          {
            "type": "raw",
            "field name": "Z Score",
            "raw field": "zScore"
          },
          {
            "type": "raw",
            "field name": "P-Value",
            "raw field": "pValue"
          },
          {
            "type": "raw",
            "field name": "rsID",
            "raw field": "dbSNP"
          },
          {
            "type": "join",
            "field name": "PhenotypeAncestry",
            "fields to join": [
              "phenotype",
              "ancestry"
            ],
            "join by": "_"
          },
          {
            "type": "join",
            "field name": "Ref/Alt",
            "fields to join": [
              "reference",
              "alt"
            ],
            "join by": "/"
          },
          {
            "type": "join",
            "field name": "Locus",
            "fields to join": [
              "chromosome",
              "position"
            ],
            "join by": ":"
          },
          {
            "type": "join multi",
            "field name": "Variant ID",
            "fields to join": [
              "chromosome",
              "position",
              "reference",
              "alt"
            ],
            "join by": [
              ":",
              "_",
              "/"
            ]
          },
          {
            "type": "join multi",
            "field name": "KP Variant ID",
            "fields to join": [
              "chromosome",
              "position",
              "reference",
              "alt"
            ],
            "join by": [
              ":",
              ":",
              ":"
            ]
          },
          {
            "type": "calculate",
            "field name": "-log10(P-Value)",
            "raw field": "pValue",
            "calculation type": "-log10"
          }
        ],
        "top rows": [
          "Variant ID",
          "PhenotypeAncestry",
          "rsID",
          "Ref/Alt",
          "P-Value",
          "Beta",
          "MAF",
          "Standard Error",
          "Z Score",
          "Consequence"
        ],
        "tool tips": {
          "Variant ID": "chromosome:position (hg19)_ref/alt",
          "rsID": "Variant ID from dbGaP",
          "Ref/Alt": "Reference allele/alternate allele",
          "P-Value": "Significance of association with the selected phenotype(s)",
          "Beta": "Effect size",
          "MAF": "Minor allele frequency",
          "Z Score": "Beta / Standard error",
          "Consequence": "Impact of the variant for overlapping genes or transcripts, as predicted by the Ensembl Variant Effect Predictor (VEP)",
          "Credible Set": "Posterior Probability of Association for the variant in the selected credible set(s)"
        },
        "star column": "Variant ID",
        "locus field": "Locus",
        "column formatting": {
          "P-Value": {
            "type": [
              "scientific notation"
            ]
          },
          "Odds Ratio": {
            "type": [
              "scientific notation"
            ]
          },
          "Beta": {
            "type": [
              "scientific notation"
            ]
          },
          "EAF": {
            "type": [
              "scientific notation"
            ]
          },
          "MAF": {
            "type": [
              "scientific notation"
            ]
          },
          "Standard Error": {
            "type": [
              "scientific notation"
            ]
          },
          "Z Score": {
            "type": [
              "scientific notation"
            ]
          },
          "Target Gene": {
            "type": [
              "link"
            ],
            "link to": "/gene.html?gene=",
            "new tab": "true"
          }
        }
      },
      "pre filters": [
        {
          "field": "P-Value",
          "value": 0.05,
          "parameter": "pValue",
          "type": "search lower than"
        }
      ],
      "filters": [
        {
          "field": "Variant ID",
          "label": "Variant ID",
          "type": "search",
          "label in bubble": "true"
        },
        {
          "field": "rsID",
          "label": "rsID",
          "type": "search",
          "label in bubble": "true"
        },
        {
          "field": "P-Value",
          "label": "P-Value (&le;)",
          "type": "search lower than",
          "label in bubble": "true"
        },
        {
          "field": "LDS",
          "label": "LD score (&ge;)",
          "type": "search greater than",
          "label in bubble": "true"
        },
